using System.Collections.Generic;
using System.Text;
using System.Web;
using System.Web.Script.Serialization;

namespace InformationWeb.Dashboards.API
{
    /// <summary>
    /// Helper dùng chung cho các API dashboard: kiểm tra đăng nhập, trả JSON redirect về form login.
    /// </summary>
    public static class DashboardApiBase
    {
        public const string LOGIN_URL = "/dang-nhap.html";

        public static bool EnsureLoggedIn(HttpContext context)
        {
            if (WebGlobal.User != null)
                return true;

            WriteJson(context, false, "Bạn chưa đăng nhập hệ thống.", null, LOGIN_URL);
            return false;
        }

        public static void WriteJson(HttpContext context, bool success, string message, object data)
        {
            WriteJson(context, success, message, data, null);
        }

        public static void WriteJson(HttpContext context, bool success, string message, object data, string redirectUrl)
        {
            context.Response.ContentType = "application/json";
            context.Response.ContentEncoding = Encoding.UTF8;

            Dictionary<string, object> dicResponse = new Dictionary<string, object>();
            dicResponse["success"] = success;
            dicResponse["message"] = message;
            dicResponse["data"] = data;
            if (redirectUrl != null && redirectUrl != "")
                dicResponse["redirectUrl"] = redirectUrl;

            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            objSerializer.MaxJsonLength = int.MaxValue;
            context.Response.Write(objSerializer.Serialize(dicResponse));
        }
    }
}

/**
 * Xử lý chung phản hồi API dashboard — chuyển về form đăng nhập khi hết session.
 */
(function (w) {
    "use strict";

    var LOGIN_URL = "/dang-nhap.html";

    function redirectIfLoginRequired(response) {
        var message;
        if (!response) {
            return false;
        }
        if (response.redirectUrl) {
            w.location.href = response.redirectUrl;
            return true;
        }
        message = response.message || "";
        if (message.indexOf("chưa đăng nhập") >= 0) {
            w.location.href = LOGIN_URL;
            return true;
        }
        return false;
    }

    w.DashboardApiUtils = {
        LOGIN_URL: LOGIN_URL,
        redirectIfLoginRequired: redirectIfLoginRequired
    };
}(window));

